const https = require('https');
const http = require('http');

function httpReq(url, options, body) {
  return new Promise((resolve, reject) => {
    const mod = url.startsWith('https') ? https : http;
    const req = mod.request(url, options, res => {
      let d = '';
      res.on('data', c => d += c);
      res.on('end', () => resolve({ status: res.statusCode, body: d }));
    });
    req.on('error', reject);
    if (body) req.write(body);
    req.end();
  });
}

const BOT_TOKEN = '{{TELEGRAM_BOT_TOKEN}}';

async function sendTelegram(chatId, text, replyMarkup) {
  const url = 'https://api.telegram.org/bot' + BOT_TOKEN + '/sendMessage';
  const payload = { chat_id: chatId, text };
  if (replyMarkup) payload.reply_markup = replyMarkup;
  await httpReq(url, { method: 'POST', headers: { 'Content-Type': 'application/json' } },
    JSON.stringify(payload));
}

async function answerCallback(callbackQueryId) {
  const url = 'https://api.telegram.org/bot' + BOT_TOKEN + '/answerCallbackQuery';
  await httpReq(url, { method: 'POST', headers: { 'Content-Type': 'application/json' } },
    JSON.stringify({ callback_query_id: callbackQueryId }));
}

async function nocoGet(path) {
  const url = 'http://nocodb:8080/api/v2' + path;
  const r = await httpReq(url, { method: 'GET', headers: { 'xc-token': '{{NOCODB_AUTH_TOKEN}}' } });
  return JSON.parse(r.body);
}

async function nocoPatch(path, body) {
  const url = 'http://nocodb:8080/api/v2' + path;
  await httpReq(url, { method: 'PATCH', headers: { 'Content-Type': 'application/json', 'xc-token': '{{NOCODB_AUTH_TOKEN}}' } },
    JSON.stringify(body));
}

async function nocoPost(path, body) {
  const url = 'http://nocodb:8080/api/v2' + path;
  await httpReq(url, { method: 'POST', headers: { 'Content-Type': 'application/json', 'xc-token': '{{NOCODB_AUTH_TOKEN}}' } },
    JSON.stringify([body]));
}

const skipButton = { inline_keyboard: [[{ text: '\u23ed Skip', callback_data: 'skip' }]] };

const input = $input.first().json;
const callbackQuery = input.callback_query;
const message = callbackQuery ? callbackQuery.message : input.message;
const text = callbackQuery ? callbackQuery.data : (input.message?.text || input.message?.caption || '');
const chatId = callbackQuery ? callbackQuery.message.chat.id : input.message.chat.id;
const staticData = $getWorkflowStaticData('global');

if (callbackQuery) {
  await answerCallback(callbackQuery.id);
}

// Clean up stale state (1 hour TTL)
if (staticData[chatId]?.ts && Date.now() - staticData[chatId].ts > 3600000) {
  delete staticData[chatId];
}

if (text === '/start') {
  const prompts = await nocoGet('/tables/{{NOCODB_PROMPTS_TABLE_ID}}/records?limit=1&fields=Id');
  if (prompts.list && prompts.list[0]) {
    await nocoPatch('/tables/{{NOCODB_PROMPTS_TABLE_ID}}/records', { Id: prompts.list[0].Id, TelegramChatId: String(chatId) });
  }
  await sendTelegram(chatId, 'Bot connected! Chat ID saved. Forward me a message to create a content plan entry.');
} else if (!callbackQuery && (input.message?.forward_date || input.message?.forward_origin)) {
  staticData[chatId] = { step: 'awaiting_topic', description: text, ts: Date.now() };
  await sendTelegram(chatId, 'Got it! Now send me the Topic for this article.');
} else if (staticData[chatId]?.step === 'awaiting_topic') {
  staticData[chatId].step = 'awaiting_link';
  staticData[chatId].topic = text;
  staticData[chatId].ts = Date.now();
  await sendTelegram(chatId, 'Topic saved. Now send me the Link (URL) for this article.', skipButton);
} else if (staticData[chatId]?.step === 'awaiting_link') {
  staticData[chatId].step = 'awaiting_board';
  staticData[chatId].link = text === 'skip' ? '' : text;
  staticData[chatId].ts = Date.now();
  await sendTelegram(chatId, 'Now send me the Pinterest Board name for this article.', skipButton);
} else if (staticData[chatId]?.step === 'awaiting_board') {
  const topic = staticData[chatId].topic;
  const description = staticData[chatId].description;
  const link = staticData[chatId].link;
  const board = text === 'skip' ? '' : text;
  delete staticData[chatId];
  const record = { Topic: topic, Description: description };
  if (link) record.Link = link;
  if (board) record.Board = board;
  await nocoPost('/tables/{{NOCODB_TABLE_ID}}/records', record);
  await sendTelegram(chatId, '\u2705 Added to content plan:\n\nTopic: ' + topic + '\nDescription: ' + description + '\nLink: ' + (link || '(default)') + '\nBoard: ' + (board || '(default)'));
} else {
  await sendTelegram(chatId, 'Forward me a message to create a content plan entry, or send /start to connect.');
}

return [{ json: { success: true } }];
